"""Fixed privileged-state guidance used for the paired reference condition."""

from dataclasses import dataclass

import numpy as np
from mpc_program import Action, CartesianProposal, ProgramObservation, Proposals


@dataclass(frozen=True)
class State:
    initial: ProgramObservation
    current: ProgramObservation
    instruction: str


def guidance(state: State) -> tuple[str, CartesianProposal]:
    observation = state.current
    tip = np.asarray(observation.tip[:3])
    target = np.array(observation.object_pose[:3])
    if state.instruction == "take lid off the saucepan":
        if observation.grasped:
            stage, gripper = "lift", 0
            target = tip + np.array(
                [0, 0, max(0, state.initial.object_pose[2] + 0.15 - target[2])]
            )
        elif np.linalg.norm(tip - target) < 0.02:
            stage, gripper = "grasp", 0
        else:
            stage, gripper = "approach", observation.gripper_command
    else:
        aligned = np.linalg.norm(tip[:2] - target[:2]) < 0.02
        stage, gripper = ("press" if aligned else "approach"), 0
        target[2] += -0.01 if aligned else 0.10
    return stage, CartesianProposal(
        target=tuple(target), quaternion=state.initial.tip[3:], gripper=gripper
    )


class ReferenceProgram:
    """Reference mean-plus-terminal objective with guidance fixed per solve."""

    def init(self, observation: ProgramObservation, instruction: str) -> State:
        return State(observation, observation, instruction)

    def advance(
        self, state: State, action: Action, observation: ProgramObservation
    ) -> State:
        return State(state.initial, observation, state.instruction)

    def proposals(self, state: State, observation: ProgramObservation) -> Proposals:
        return (guidance(state)[1],)

    def trajectory_cost(
        self,
        initial: State,
        states: tuple[State, ...],
        observations: tuple[ProgramObservation, ...],
    ) -> float:
        stage, proposal = guidance(initial)
        costs = []
        for observation in observations:
            guide = np.sum((np.asarray(observation.tip[:3]) - proposal.target) ** 2)
            if initial.instruction == "take lid off the saucepan":
                task = (
                    max(
                        0,
                        initial.initial.object_pose[2]
                        + 0.15
                        - observation.object_pose[2],
                    )
                    ** 2
                )
                grasp = float(stage in ("grasp", "lift") and not observation.grasped)
            else:
                assert observation.button_displacement is not None
                task = max(0, 0.003 - abs(observation.button_displacement)) ** 2
                grasp = 0.0
            costs.append(100 * guide + 200 * task + 2 * grasp)
        return float(np.mean(costs) + costs[-1])


program = ReferenceProgram()

from dataclasses import dataclass
import numpy as np
from mpc_program import CartesianProposal, ProgramObservation, Proposals

@dataclass(frozen=True)
class State:
    initial: ProgramObservation
    current: ProgramObservation
    instruction: str

def _clip_xy(target_xy: np.ndarray, center_xy: np.ndarray, max_radius: float = 0.30) -> np.ndarray:
    delta = target_xy - center_xy
    dist = float(np.linalg.norm(delta))
    if dist <= max_radius or dist == 0.0:
        return target_xy
    return center_xy + delta * (max_radius / dist)

def guidance(state: State) -> tuple[str, CartesianProposal]:
    observation = state.current
    tip = np.asarray(observation.tip[:3], dtype=float)
    target = np.array(observation.object_pose[:3], dtype=float)
    quat = state.initial.tip[3:]
    if state.instruction == "take lid off the saucepan":
        if observation.grasped:
            stage, gripper = "lift", 0
            target = tip + np.array([0.0, 0.0, max(0.0, state.initial.object_pose[2] + 0.15 - target[2])])
        elif np.linalg.norm(tip - target) < 0.02:
            stage, gripper = "grasp", 0
        else:
            stage, gripper = "approach", observation.gripper_command
    else:
        base_xy = np.asarray(state.initial.tip[:2], dtype=float)
        target[:2] = _clip_xy(target[:2], base_xy, 0.30)
        aligned = np.linalg.norm(tip[:2] - target[:2]) < 0.02
        stage, gripper = ("press" if aligned else "approach"), 0
        target[2] += -0.01 if aligned else 0.10
    return stage, CartesianProposal(target=tuple(target), quaternion=quat, gripper=gripper)

class ImprovedProgram:
    def init(self, observation: ProgramObservation, instruction: str) -> State:
        return State(observation, observation, instruction)
    def advance(self, state: State, action, observation: ProgramObservation) -> State:
        return State(state.initial, observation, state.instruction)
    def proposals(self, state: State, observation: ProgramObservation) -> Proposals:
        return (guidance(state)[1],)
    def trajectory_cost(self, initial: State, states, observations) -> float:
        stage, proposal = guidance(initial)
        target = np.asarray(proposal.target, dtype=float)
        costs = []
        for observation in observations:
            tip = np.asarray(observation.tip[:3], dtype=float)
            guide = np.sum((tip - target) ** 2)
            if initial.instruction == "take lid off the saucepan":
                task = max(0.0, initial.initial.object_pose[2] + 0.15 - observation.object_pose[2]) ** 2
                grasp = float(stage in ("grasp", "lift") and not observation.grasped)
                costs.append(100.0 * guide + 200.0 * task + 2.0 * grasp)
            else:
                disp = float(abs(observation.button_displacement or 0.0))
                task = max(0.0, 0.003 - disp) ** 2
                xy_err = np.sum((tip[:2] - target[:2]) ** 2)
                below = max(0.0, tip[2] - (target[2] + 0.01))
                costs.append(120.0 * guide + 80.0 * xy_err + 120.0 * below * below + 400.0 * task)
        return float(np.mean(costs) + costs[-1])
